                            .formatted(requiredRight.right().getName(), requiredRight.scope().getLowerCase()));
                    break;
                }
            }
        }
    }

@Override
    public int read(byte[] buf, int off, int len) throws IOException {
        checkMaxBytesRead();

        // Calculate the maximum number of bytes that we should try to read.
        int num = Math.min(len, maxBytesRead - numRead + 1);

        int b = super.read(buf, off, num);

        if (b != -1) {
            numRead += b;
        }
        return b;
    }

@Override
    public int read(byte[] buf, int off, int len) throws IOException {
        checkMaxBytesRead();

        // Calculate the maximum number of bytes that we should try to read.
        int num = Math.min(len, maxBytesRead - numRead + 1);

        int b = super.read(buf, off, num);

        if (b > 0) {
            numRead += b;
        }

        checkMaxBytesRead();
        return b;
    }

public static URL find(String path) throws Exception {
        URL rst = null;

        if (path.contains("/../") == false) {
            // '/../' 不安全，禁止进入静态资料库
            for (StaticLocation m : locationMap.values()) {
                if (path.startsWith(m.pathPrefix)) {
                    if (m.repositoryIncPrefix) {
                        //path = /demo/file.htm
                        //relativePath = demo/file.htm （没有'/'开头）
                        rst = m.repository.find(path.substring(1));
                    } else {
                        //path = /demo/file.htm
                        //relativePath = demo/file.htm （没有'/'开头）
                        if (m.pathPrefixAsFile) {
                            //如果是文件
                            int idx = m.pathPrefix.lastIndexOf("/");
                            rst = m.repository.find(m.pathPrefix.substring(idx + 1));
                        } else {
                            //如果是路段
                            rst = m.repository.find(path.substring(m.pathPrefix.length()));
                        }
                    }

                    if (rst != null) {
                        return rst;
                    }
                }
            }
        }

        return rst;
    }

