public ChecksumCalculator(@Nullable Collection<String> algs) throws NoSuchAlgorithmException {
    if (CollectionUtils.isNotEmpty(algs)) {
        for (String alg : algs) {
            if (alg.equals("CRC32")) {
                setUseCrc(true);
            } else if (alg.equals("SSDEEP")) {
                setUseSsdeep(true);
            } else {
                digest.add(MessageDigest.getInstance(alg));
            }
        }
    }
}

