@Override
    public Resource loadAsResource(String filename) {
        try {
            Path location = Paths.get(rootLocation+"/");
            Path file = load(filename,location);
            Resource resource = new UrlResource(file.toUri());
            if (resource.exists() || resource.isReadable()) {
                return resource;
            }
            else {
              return null;
            }
        } catch (MalformedURLException e) {
           log.error("[EXCEPTION] loadAsResource: {},{}",e.getMessage(),e.getCause());
           return null;
        }
    }

public File createTempFile(final String prefix, final String suffix) {
        try {
            final File file = File.createTempFile(prefix, suffix);
            file.setReadable(false, false);
            file.setReadable(true, true);
            file.setWritable(false, false);
            file.setWritable(true, true);
            if (logger.isDebugEnabled()) {
                logger.debug("Create {} as a temp file.", file.getAbsolutePath());
            }
            return file;
        } catch (final IOException e) {
            throw new IORuntimeException(e);
        }
    }

