            int literalLength = token >>> 4; // top-most 4 bits of token
            if (literalLength == 0xF) {
                if (input >= inputLimit) {
                    throw new MalformedInputException(input - inputAddress);
                }
                int value;
                do {
                    value = UNSAFE.getByte(inputBase, input++) & 0xFF;
                    literalLength += value;
                }
                while (value == 255 && input < inputLimit - 15);
            }
            if (literalLength < 0) {
                throw new MalformedInputException(input - inputAddress);
            }

